UPDATE TB_EOS_RESOURCE
   SET EOS_STATUS_CD = #{eosStatusCd},
       CHG_USER_ID = #{chgUserId},
       CHG_DTM = #{chgDtm}
 WHERE RESOURCE_ID = #{resourceId}

UPDATE TB_EOS_EXC_REQ
   SET STATUS_CD = 'EXPIRED',
       CHG_USER_ID = #{chgUserId},
       CHG_DTM = #{chgDtm}
 WHERE EXC_REQ_ID = #{excReqId}
   AND STATUS_CD IN ('APPROVED', 'CONDITIONAL')

UPDATE TB_EOS_RESOURCE
   SET EXCEPTION_ACTIVE_YN = 'N',
       CHG_USER_ID = #{chgUserId},
       CHG_DTM = #{chgDtm}
 WHERE RESOURCE_ID = #{resourceId}
   AND EXCEPTION_ACTIVE_YN = 'Y'

